create extension if not exists pgcrypto;
create type public.incident_status as enum ('investigating','identified','monitoring','resolved');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz not null default now());
create table public.providers(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,category text not null,integration_type text not null default 'statuspage' check(integration_type='statuspage'),status_url text not null check(status_url ~ '^https://'),enabled boolean not null default false,current_status text,last_checked_at timestamptz,created_at timestamptz not null default now());
create table public.incidents(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.providers(id) on delete cascade,source_event_id text not null,title text not null,status public.incident_status not null default 'investigating',impact text,shortlink text,source_url text,created_at timestamptz not null,updated_at timestamptz not null,unique(provider_id,source_event_id));
create table public.ingestion_runs(id uuid primary key default gen_random_uuid(),started_at timestamptz not null,completed_at timestamptz,providers_checked integer not null default 0,status text not null check(status in ('running','completed','failed')),error_summary text);
create table public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,provider_id uuid references public.providers(id) on delete cascade,category text,created_at timestamptz not null default now(),check(provider_id is not null or category is not null));
create index incidents_updated_idx on public.incidents(updated_at desc);create index incidents_status_idx on public.incidents(status);create index incidents_provider_idx on public.incidents(provider_id);create index ingestion_completed_idx on public.ingestion_runs(completed_at desc);create index subscriptions_user_idx on public.subscriptions(user_id);